from pathlib import Path
T=Path('src/main/resources/templates/customer')
def page(name,title,body):
 (T/(name+'.html')).write_text('''<!DOCTYPE html><html xmlns:th="http://www.thymeleaf.org" lang="vi"><head th:replace="~{fragments/head :: head(title='''+"'"+title+"'"+''')}"></head><body class="bg-surface text-on-surface"><div th:replace="~{fragments/customer-header :: header(isHome=false)}"></div><main class="customer-workspace"><div class="cw-tabs"><a href="/customer/my-rentals">Đơn đang thuê</a><a href="/customer/rental-history">Lịch sử</a><a href="/customer/profile">Hồ sơ cá nhân</a></div><h1>'''+title+'''</h1><div id="cw-message" class="cw-message" role="status" aria-live="polite"></div>'''+body+'''</main><div th:replace="~{fragments/customer-footer :: footer}"></div><script src="/js/customer.js" defer></script></body></html>''',encoding='utf-8')
def field(name,label,typ='text',extra=''):
 return f'<label class="cw-field">{label}<input name="{name}" type="{typ}" {extra}></label>'
profile='<p class="cw-muted">Cập nhật thông tin liên hệ và bảo mật tài khoản của bạn.</p><section class="cw-card"><div class="cw-row"><h2>Thông tin cá nhân</h2><img class="cw-avatar" th:src="${@display.image(customer.avatar)}" alt="Ảnh đại diện"></div><form id="avatar-form" class="cw-actions"><input type="file" name="file" accept="image/jpeg,image/png" required aria-label="Ảnh đại diện JPG hoặc PNG"><button class="cw-btn">Lưu ảnh đại diện</button></form><form id="account-form" class="cw-grid" style="margin-top:24px">'
for n,l,ty,ex in [('firstName','Tên','text','required maxlength="100"'),('lastName','Họ và tên đệm','text','required maxlength="100"'),('email','Email','email','required'),('phone','Số điện thoại','tel','required'),('birthDate','Ngày sinh','date',''),('address','Địa chỉ','text','maxlength="255"')]:
 profile+=field(n,l,ty,ex+f' th:value="${{customer.{n}}}"')
profile+='''<label class="cw-field">Giới tính<select name="gender"><option value="" th:selected="${customer.gender == null}">Chưa cung cấp</option><option value="true" th:selected="${customer.gender == true}">Nam</option><option value="false" th:selected="${customer.gender == false}">Nữ</option></select></label><div class="cw-actions"><button class="cw-btn primary">Lưu thông tin</button></div></form></section><section class="cw-card"><h2>Đổi mật khẩu</h2><form id="password-form" class="cw-grid">'''
for n,l in [('currentPassword','Mật khẩu hiện tại'),('newPassword','Mật khẩu mới'),('confirmPassword','Nhập lại mật khẩu mới')]:profile+=field(n,l,'password','required minlength="8" maxlength="72" autocomplete="'+('current-password' if n=='currentPassword' else 'new-password')+'"')
profile+='<div class="cw-actions"><button class="cw-btn primary">Cập nhật mật khẩu</button></div></form></section>'
page('profile','Hồ sơ cá nhân',profile)
card='''<div th:if="${#lists.isEmpty(rentals)}" class="cw-card"><h2>Chưa có đơn thuê phù hợp</h2><a class="cw-btn primary" href="/customer/motorbike-list">Chọn xe</a></div>
<article class="cw-card" th:each="rental : ${rentals}"><div class="cw-row"><strong th:text="${rental.orderCode}"></strong><span class="cw-tag" th:text="${@display.status(rental.status)}"></span></div><div class="cw-order"><img th:src="${@display.image(rental.motorbike.imagePrimary)}" th:alt="${rental.motorbikeName}"><div><h2 th:text="${rental.motorbikeName}"></h2><span class="cw-price" th:text="${@display.money(rental.totalPrice)}"></span><div class="cw-facts"><span th:text="${'Nhận: ' + @display.date(rental.pickupDate)}"></span><span th:text="${'Trả: ' + @display.date(rental.returnDate)}"></span><span th:text="${rental.days + ' ngày'}"></span><span th:text="${'Đã trả: ' + @display.money((rental.depositPaid ?: 0) + (rental.balancePaid ?: 0))}"></span></div><p class="cw-muted" th:if="${rental.rejectionReason != null}" th:text="${rental.rejectionReason}"></p></div></div><div class="cw-actions"><a class="cw-btn" th:href="@{/customer/rental-detail/{id}(id=${rental.id})}">Xem chi tiết</a><button class="cw-btn primary" th:if="${rental.status == 'PENDING_PAYMENT'}" data-action="pay" th:data-id="${rental.id}">Thanh toán cọc</button><button class="cw-btn" th:if="${rental.status == 'PENDING_PAYMENT' || rental.status == 'PENDING'}" data-action="cancel" th:data-id="${rental.id}">Hủy đơn</button><a class="cw-btn" th:if="${rental.status == 'HANDED_OVER' || rental.status == 'EXTENDED'}" th:href="@{/customer/rental-extension/{id}(id=${rental.id})}">Yêu cầu gia hạn</a><a class="cw-btn" th:if="${rental.status == 'COMPLETED' || rental.status == 'CANCELLED' || rental.status == 'REJECTED'}" th:href="@{/customer/motorbike-detail/{id}(id=${rental.motorbike.id})}">Thuê lại xe này</a></div><p class="cw-muted" th:if="${rental.status == 'PENDING_PAYMENT' && rental.paymentExpiresAt != null}" th:text="${'Hạn thanh toán: '+@display.date(rental.paymentExpiresAt)}"></p></article>'''
page('my-rentals','Đơn thuê của tôi','<p class="cw-muted">Theo dõi xác nhận, bàn giao và thanh toán cho chuyến đi.</p>'+card)
history='''<p class="cw-muted">Xem lại chuyến đi đã hoàn tất và các đơn đã hủy hoặc từ chối.</p><div class="cw-tabs"><span th:text="${'Tất cả: '+totalHistoryCount}"></span><span th:text="${'Hoàn tất: '+completedCount}"></span><span th:text="${'Hủy hoặc từ chối: '+cancelledCount}"></span></div><form class="cw-filter" method="get"><input name="q" th:value="${q}" placeholder="Tìm theo mã đơn hoặc tên xe" aria-label="Tìm đơn"><select name="status" aria-label="Trạng thái"><option value="ALL">Tất cả</option><option value="COMPLETED" th:selected="${status == 'COMPLETED'}">Hoàn tất</option><option value="CANCELLED" th:selected="${status == 'CANCELLED'}">Đã hủy hoặc từ chối</option></select><select name="months" aria-label="Thời gian"><option value="0">Tất cả thời gian</option><option value="3" th:selected="${months == 3}">3 tháng gần nhất</option><option value="6" th:selected="${months == 6}">6 tháng gần nhất</option></select><button class="cw-btn primary">Lọc lịch sử</button></form>'''+card+'''<div class="cw-row"><span th:text="${total + ' đơn · Trang ' + (page+1) + '/' + pages}"></span><div class="cw-actions"><a class="cw-btn" th:if="${page>0}" th:href="@{/customer/rental-history(page=${page-1},status=${status},q=${q},months=${months})}">Trang trước</a><a class="cw-btn" th:if="${page+1<pages}" th:href="@{/customer/rental-history(page=${page+1},status=${status},q=${q},months=${months})}">Trang sau</a></div></div>'''
page('rental-history','Lịch sử thuê xe',history)
summary='''<section class="cw-card"><div class="cw-row"><h2 th:text="${rental.orderCode}"></h2><span class="cw-tag" th:text="${@display.status(rental.status)}"></span></div><div class="cw-order"><img th:src="${@display.image(rental.motorbike.imagePrimary)}" th:alt="${rental.motorbike.name}"><div><h2 th:text="${rental.motorbike.name}"></h2><span class="cw-price" th:text="${@display.money(rental.totalPrice)}"></span><div class="cw-facts"><span th:text="${'Nhận: '+@display.date(rental.pickupDate)}"></span><span th:text="${'Trả: '+@display.date(rental.returnDate)}"></span><span th:text="${'Đã trả: '+@display.money((rental.depositPaid ?: 0)+(rental.balancePaid ?: 0))}"></span><span th:text="${'Còn lại: '+@display.money(rental.totalPrice-(rental.depositPaid ?: 0)-(rental.balancePaid ?: 0))}"></span></div><p class="cw-muted" th:text="${rental.pickupAddress ?: 'Nhận tại cửa hàng'}"></p><p class="cw-muted" th:text="${rental.returnAddress ?: 'Trả tại cửa hàng'}"></p><p th:if="${rental.rejectionReason != null}" th:text="${rental.rejectionReason}"></p></div></div></section>'''
payment_table='''<section class="cw-card"><h2>Giao dịch thanh toán</h2><p class="cw-muted" th:if="${#lists.isEmpty(payments)}">Chưa có giao dịch được lưu.</p><div class="cw-scroll"><table class="cw-table" th:unless="${#lists.isEmpty(payments)}"><thead><tr><th>Số tiền</th><th>Hình thức</th><th>Trạng thái</th><th>Thời điểm nhận</th></tr></thead><tbody><tr th:each="p : ${payments}"><td th:text="${@display.money(p.amount)}"></td><td th:text="${p.method == 'PAYOS' ? 'PayOS' : 'Tiền mặt'}"></td><td th:text="${@display.status(p.status)}"></td><td th:text="${@display.date(p.paidAt)}"></td></tr></tbody></table></div></section>'''
page('rental-detail','Chi tiết đơn thuê',summary+'''<div class="cw-actions"><button class="cw-btn primary" data-action="pay" th:data-id="${rental.id}" th:if="${rental.status.name() == 'PENDING_PAYMENT'}">Thanh toán cọc</button><a class="cw-btn" th:if="${rental.status.name() == 'COMPLETED' && !reviewed}" th:href="@{/customer/review/{id}(id=${rental.id})}">Đánh giá chuyến đi</a><span th:if="${reviewed}" class="cw-tag">Bạn đã đánh giá chuyến đi này</span><button class="cw-btn" onclick="window.print()">In thông tin đơn thuê</button></div>'''+payment_table+'''<section class="cw-card"><h2>Yêu cầu gia hạn</h2><p th:if="${#lists.isEmpty(extensions)}" class="cw-muted">Chưa có yêu cầu gia hạn.</p><div th:each="e : ${extensions}" class="cw-facts"><span th:text="${@display.date(e.newReturnDate)}"></span><span th:text="${@display.money(e.extraAmount)}"></span><span th:text="${@display.status(e.status)}"></span><span th:text="${e.reason}"></span></div></section><section class="cw-card" th:if="${contract != null}"><h2>Biên bản bàn giao</h2><p th:text="${contract.contractCode}"></p><p th:text="${contract.vehicleConditionBefore}"></p><p th:text="${contract.vehicleConditionAfter}"></p><div class="cw-facts"><span th:text="${'Công tơ mét lúc giao: '+(contract.odoBefore ?: 0)+' km'}"></span><span th:text="${'Công tơ mét lúc trả: '+(contract.odoAfter ?: 0)+' km'}"></span></div></section>''')
page('payment-result','Trạng thái thanh toán',summary+'''<p class="cw-message">Trạng thái được cập nhật sau khi đối soát giao dịch. Nếu vừa chuyển tiền, hãy kiểm tra lại thanh toán.</p><div class="cw-actions"><button class="cw-btn primary" data-action="reconcile" th:data-id="${rental.id}">Kiểm tra lại thanh toán</button><a class="cw-btn" href="/customer/my-rentals">Đơn thuê của tôi</a></div>'''+payment_table)
page('rental-extension','Yêu cầu gia hạn',summary+'''<section class="cw-card"><form id="extension-form" th:data-id="${rental.id}" class="cw-grid"><label class="cw-field">Ngày trả mới<input type="datetime-local" name="newReturnDate" required th:min="${rental.returnDate}"></label><label class="cw-field">Lý do<textarea name="reason" maxlength="1000" required></textarea></label><p class="cw-muted cw-full">Cửa hàng sẽ kiểm tra lịch xe và duyệt yêu cầu. Phí phát sinh tính theo giá ngày đã chốt trong đơn; gửi yêu cầu chưa có nghĩa là được gia hạn.</p><button class="cw-btn primary">Gửi yêu cầu</button></form></section>''')
page('review','Đánh giá chuyến đi',summary+'''<section class="cw-card"><form id="review-form" th:data-id="${rental.id}" class="cw-grid"><label class="cw-field">Mức hài lòng<select name="rating" required><option value="">Chọn số sao</option><option value="5">5 sao · Rất hài lòng</option><option value="4">4 sao · Hài lòng</option><option value="3">3 sao · Bình thường</option><option value="2">2 sao · Chưa hài lòng</option><option value="1">1 sao · Không hài lòng</option></select></label><label class="cw-field cw-full">Nhận xét<textarea name="comment" rows="4" maxlength="2000" required></textarea></label><button class="cw-btn primary">Gửi đánh giá</button></form></section>''')
page('motorbike-detail','Chi tiết xe','''<div class="cw-specs"><section class="cw-card"><img class="cw-hero-image" id="bike-image" th:src="${@display.image(motorbike.imagePrimary)}" th:alt="${motorbike.name}"><div class="cw-gallery"><button th:each="url : ${motorbike.allImages}" type="button" data-gallery><img th:src="${@display.image(url)}" alt="Ảnh xe"></button></div></section><section class="cw-card"><p class="cw-muted" th:text="${motorbike.brand + ' · ' + motorbike.category}"></p><h2 th:text="${motorbike.name}"></h2><div class="cw-price" th:text="${@display.money(motorbike.pricePerDay) + ' / ngày'}"></div><div class="cw-facts"><span th:text="${'Đời xe: '+motorbike.year}"></span><span th:text="${'Dung tích: '+motorbike.cc+' cc'}"></span><span th:text="${'Đánh giá: '+motorbike.rating+' / 5'}"></span><span th:text="${motorbike.reviewCount+' đánh giá'}"></span><span th:text="${motorbike.transmission}"></span><span th:text="${@display.status(motorbike.status)}"></span></div><p class="cw-muted" th:text="${motorbike.description}"></p><p th:text="${motorbike.highlights}"></p><div class="cw-actions"><a class="cw-btn primary" data-preserve-query th:unless="${motorbike.status == 'MAINTENANCE' || motorbike.status == 'UNAVAILABLE'}" th:href="@{/customer/rental-contract/{id}(id=${motorbike.id})}">Chọn thời gian và đặt xe</a><a class="cw-btn" href="/customer/motorbike-list">Xem xe khác</a></div></section></div><section class="cw-card"><h2>Đánh giá từ khách thuê</h2><p th:if="${#lists.isEmpty(bikeReviews)}" class="cw-muted">Chưa có đánh giá cho xe này.</p><div th:each="r : ${bikeReviews}" style="padding:14px 0;border-bottom:1px solid #ffffff18"><strong th:text="${r.rating + ' / 5'}"></strong><p th:text="${r.comment}"></p><p class="cw-muted" th:if="${r.staffReply != null}" th:text="${'Phản hồi cửa hàng: '+r.staffReply}"></p></div></section>''')
# Route aliases are handled by the controller. Remove dormant demo templates from deployable resources.
for n in ['edit-profile','payment']:
 page(n,'Tài khoản','<a class="cw-btn primary" href="/customer/profile">Về hồ sơ cá nhân</a>')
